:root { --ink:#1f2328; --muted:#59636e; --line:#e4e8ec; --brand:#0e7490; --brand2:#06b6d4; }
* { margin:0; padding:0; box-sizing:border-box; }
body { font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif; color:var(--ink); background:#fafbfc; }
a { color:inherit; }

header { background:linear-gradient(120deg,var(--brand),var(--brand2)); color:#fff; padding:36px 24px 0; text-align:center; }
header h1 { font-size:26px; letter-spacing:-0.3px; }
header p { opacity:.9; margin-top:6px; font-size:14px; }
#clock { margin-top:10px; font-size:12px; opacity:.75; font-variant-numeric:tabular-nums; }
nav { display:flex; justify-content:center; gap:4px; margin-top:22px; }
nav a { text-decoration:none; font-size:13px; font-weight:600; padding:9px 14px; border-radius:8px 8px 0 0; opacity:.85; }
nav a[aria-current="page"] { background:#fafbfc; color:var(--ink); opacity:1; }

main { max-width:860px; margin:0 auto; padding:32px 24px 56px; }
h2 { font-size:17px; margin:30px 0 14px; padding-bottom:8px; border-bottom:1px solid var(--line); }
section:first-of-type h2 { margin-top:0; }
.lede { color:var(--muted); font-size:14px; line-height:1.6; }

/* home */
.feature { display:grid; grid-template-columns:1.2fr 1fr; gap:18px; align-items:center; background:#fff; border:1px solid var(--line); border-radius:14px; overflow:hidden; }
.feature .art { height:180px; background:linear-gradient(135deg,#0ea5e9,#6366f1); }
.feature .copy { padding:20px 22px 20px 0; }
.feature h3 { font-size:18px; margin-bottom:8px; }
.feature .price { margin-top:12px; font-weight:700; color:var(--brand); }
.alert { border-radius:10px; padding:12px 14px; font-size:13.5px; margin-bottom:10px; }
.alert-ok { background:#e8f6ee; color:#1a7f37; border:1px solid #b7e2c6; }
.alert-err { background:#fdecea; color:#cf222e; border:1px solid #f5c6c0; }
.perks { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
.perk { background:#fff; border:1px solid var(--line); border-radius:12px; padding:14px; }
.perk h3 { font-size:14px; margin-bottom:6px; }
.perk p { font-size:12.5px; color:var(--muted); line-height:1.55; }

/* buttons */
.row { display:flex; gap:12px; flex-wrap:wrap; align-items:center; }
.row + .row { margin-top:14px; }
.btn { padding:10px 20px; border-radius:8px; border:1px solid transparent; font-size:14px; font-weight:600; cursor:pointer; font-family:inherit; }
.btn-primary { background:var(--brand); color:#fff; }
.btn-secondary { background:#fff; color:var(--ink); border-color:var(--line); }
.btn-danger { background:#cf222e; color:#fff; }
.btn-sm { padding:6px 12px; font-size:12.5px; }
.btn-lg { padding:13px 26px; font-size:15px; }
.btn[disabled] { opacity:.5; cursor:not-allowed; }
.signup { display:flex; gap:10px; }
.signup input { flex:1; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:14px; font-family:inherit; }

/* products */
.cards { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
.card { background:#fff; border:1px solid var(--line); border-radius:12px; overflow:hidden; }
.card .thumb { height:88px; }
.t1 { background:linear-gradient(135deg,#0ea5e9,#6366f1); }
.t2 { background:linear-gradient(135deg,#f59e0b,#ef4444); }
.t3 { background:linear-gradient(135deg,#10b981,#0e7490); }
.t4 { background:linear-gradient(135deg,#a855f7,#ec4899); }
.t5 { background:linear-gradient(135deg,#64748b,#0f172a); }
.t6 { background:linear-gradient(135deg,#facc15,#84cc16); }
.card .body { padding:14px; }
.card h3 { font-size:14px; margin-bottom:6px; }
.card p { font-size:12.5px; color:var(--muted); line-height:1.55; min-height:3.1em; }
.card .price { margin-top:10px; font-weight:700; color:var(--brand); }

footer { text-align:center; color:var(--muted); font-size:12px; padding:22px; border-top:1px solid var(--line); }
