for(let i=0;i<n;i++){
  const flags=d[o++], idx=flags&0x3f;
  let tag;
  if(idx===0x3f){tag=d.toString('latin1',o,o+4);o+=4;} else tag=KNOWN[idx];
  const orig=b128();
  const tv=(flags>>6)&3;
  let trans=null;
  if(((tag==='glyf'||tag==='loca')&&tv===0)||((tag!=='glyf'&&tag!=='loca')&&tv!==0)) trans=b128();
  tables.push({tag,orig,trans,tv});
}
// now table data begins at o; compressed streams are sequential, each compressed length = next offset - current.
// We don't know compressed lengths directly; WOFF2 spec: streams are concatenated, totalCompressedSize known.
// Decompress each expecting origLength bytes consumed; we can feed the remaining buffer each time and use brotli's
// ability to ignore trailing? Node brotliDecompressSync requires exact stream but tolerates trailing garbage? Let's try.
let off=o;
for(const t of tables){
  if(t.thead) continue;
  const rest=d.subarray(off);
  try{
    const out=zlib.brotliDecompressSync(rest);
    t.data=out; t.clen=rest.length-out.length; // not reliable
    console.log('decompressed',t.tag,'to',out.length,'expected',t.orig);
  }catch(e){
    console.log('fail',t.tag,e.message);
    break;
  }
  // find consumed length: recompress not safe. We'll instead use totalCompressedSize accounting later.
  break;
}
