  m=$(compare -metric AE "$B/${name}__${vn}/current.png" "$TMPDIR/fixed-${name}__${vn}.png" null: 2>&1)
  echo "${name}__${vn}: ${m} differing pixels"
done; done
exit $RC

cat > "$TMPDIR/shotone.js" <<'EOF'
const { chromium } = require('@playwright/test');
(async () => {
  const url = process.argv[2], out = process.argv[3];
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width:390, height:844 } });
  const p = await ctx.newPage();
  await p.goto(url, { waitUntil:'networkidle' });
  await p.screenshot({ path: out, fullPage:true });
  await browser.close();
})();
EOF
PORT=4217 node /tmp/avb-template-WMLZpz/project/server.js > "$TMPDIR/tplserver.log" 2>&1 & SPID=$!; sleep 1; NODE_PATH=/tmp/avb-Q09Jx9/project/node_modules node "$TMPDIR/shotone.js" "http://127.0.0.1:4217/orders.html" "$TMPDIR/tpl-orders-phone.png"; kill $SPID 2>/dev/null
